  /**
   * @method
   * @name cex#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see https://trade.cex.io/docs/#rest-private-api-calls-account-status-v3
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {object} [params.method] 'privatePostGetMyWalletBalance' or
   * 'privatePostGetMyAccountStatusV3'
   * @param {object} [params.account]  in case 'privatePostGetMyAccountStatusV3'
   * is chosen, this can specify the account name (default is empty string)
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<std::any>
  fetchBalance(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any accountName = std::any{};
                 std::any accountNameparamsVariable = this->handleParamString(
                     params, std::string("account"), std::string(""));
                 accountName = ::getValue(accountNameparamsVariable, 0);
                 params = ::getValue(accountNameparamsVariable,
                                     1); // default is empty string
                 std::any method = std::any{};
                 std::any methodparamsVariable = this->handleParamString(
                     params, std::string("method"),
                     std::string("privatePostGetMyWalletBalance"));
                 method = ::getValue(methodparamsVariable, 0);
                 params = ::getValue(methodparamsVariable, 1);
                 std::any accountBalance = std::any{};
                 if (isTrue(isEqual(
                         method,
                         std::string("privatePostGetMyAccountStatusV3")))) {
                   std::any response = awaitValue(
                       this->privatePostGetMyAccountStatusV3(params));
                   //
                   //    {
                   //        "ok": "ok",
                   //        "data": {
                   //            "convertedCurrency": "USD",
                   //            "balancesPerAccounts": {
                   //                "": {
                   //                    "AI": {
                   //                        "balance": "0.000000",
                   //                        "balanceOnHold": "0.000000"
                   //                    },
                   //                    ....
                   //
                   std::any data = this->safeDict(response, std::string("data"),
                                                  ccxt::dict{});
                   std::any balances = this->safeDict(
                       data, std::string("balancesPerAccounts"), ccxt::dict{});
                   accountBalance =
                       this->safeDict(balances, accountName, ccxt::dict{});
                 } else {
                   std::any response =
                       awaitValue(this->privatePostGetMyWalletBalance(params));
                   //
                   //    {
                   //        "ok": "ok",
                   //        "data": {
                   //            "AI": {
                   //                "balance": "25.606429"
                   //            },
                   //            "USDT": {
                   //                "balance": "7.935449"
                   //            },
                   //            ...
                   //
                   accountBalance = this->safeDict(
                       response, std::string("data"), ccxt::dict{});
                 }
                 return this->parseBalance(accountBalance);
               })
        .share();
  }

  std::any parseBalance(std::any response) override {
    std::any result = ccxt::dict{
        {std::string("info"), response},
    };
    std::any keys = getObjectKeys(response);
    for (std::any i = 0; isLessThan(i, getArrayLength(keys));
         postFixIncrement(i)) {
      std::any key = ::getValue(keys, i);
      std::any balance = this->safeDict(response, key, ccxt::dict{});
      std::any code = this->safeCurrencyCode(key);
      std::any account = ccxt::dict{
          {std::string("used"),
           this->safeString(balance, std::string("balanceOnHold"))},
          {std::string("total"),
           this->safeString(balance, std::string("balance"))},
      };
      if (isTrue(!isEqual(code, std::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name cex#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see https://trade.cex.io/docs/#rest-private-api-calls-orders
   * @param {string} status order status to fetch for
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest entry
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchOrdersByStatus(std::any status, std::any symbol = std::any{},
                      std::any since = std::any{}, std::any limit = std::any{},
                      std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any isClosedOrders =
                     (isEqual(status, std::string("closed")));
                 if (isTrue(isClosedOrders)) {
                   ::setValue(request, std::string("archived"), true);
                 }
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("pair"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("pageSize"), limit);
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("serverCreateTimestampFrom"),
                              since);
                 } else if (isTrue(isClosedOrders)) {
                   // exchange requires a `since` parameter for closed orders,
                   // so set default to allowed 365
                   ::setValue(
                       request, std::string("serverCreateTimestampFrom"),
                       subtract(
                           this->milliseconds(),
                           multiply(
                               multiply(multiply(multiply(364, 24), 60), 60),
                               1000)));
                 }
                 std::any until = std::any{};
                 std::any untilparamsVariable = this->handleParamInteger2(
                     params, std::string("until"), std::string("till"));
                 until = ::getValue(untilparamsVariable, 0);
                 params = ::getValue(untilparamsVariable, 1);
                 if (isTrue(!isEqual(until, std::any{}))) {
                   ::setValue(request, std::string("serverCreateTimestampTo"),
                              until);
                 }
                 std::any response = awaitValue(this->privatePostGetMyOrders(
                     this->extend(request, params)));
                 //
                 // if called without `pair`
                 //
                 //    {
                 //        "ok": "ok",
                 //        "data": [
                 //            {
                 //                "orderId": "1313003",
                 //                "clientOrderId": "037F0AFEB93A",
                 //                "clientId": "up421412345",
                 //                "accountId": null,
                 //                "status": "FILLED",
                 //                "statusIsFinal": true,
                 //                "currency1": "AI",
                 //                "currency2": "USDT",
                 //                "side": "BUY",
                 //                "orderType": "Market",
                 //                "timeInForce": "IOC",
                 //                "comment": null,
                 //                "rejectCode": null,
                 //                "rejectReason": null,
                 //                "initialOnHoldAmountCcy1": null,
                 //                "initialOnHoldAmountCcy2": "10.23456700",
                 //                "executedAmountCcy1": "25.606429",
                 //                "executedAmountCcy2": "10.20904439",
                 //                "requestedAmountCcy1": null,
                 //                "requestedAmountCcy2": "10.20904439",
                 //                "originalAmountCcy2": "10.23456700",
                 //                "feeAmount": "0.02552261",
                 //                "feeCurrency": "USDT",
                 //                "price": null,
                 //                "averagePrice": "0.3986",
                 //                "clientCreateTimestamp": "1728474625320",
                 //                "serverCreateTimestamp": "1728474624956",
                 //                "lastUpdateTimestamp": "1728474628015",
                 //                "expireTime": null,
                 //                "effectiveTime": null
                 //            },
                 //            ...
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseOrders(data, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name cex#fetchClosedOrders
   * @see https://trade.cex.io/docs/#rest-private-api-calls-orders
   * @description fetches information on multiple canceled orders made by the
   * user
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] timestamp in ms of the earliest order, default is
   * undefined
   * @param {int} [limit] max number of orders to return, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchClosedOrders(std::any symbol = std::any{}, std::any since = std::any{},
                    std::any limit = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 return awaitValue(this->fetchOrdersByStatus(
                     std::string("closed"), symbol, since, limit, params));
               })
        .share();
  }

